matchStrings:
(
  $doc := $type($) = "array" ? $[0] : $;
  $reduce([$each($doc, function($group, $gk) {
    ($type($group) = "object" and $gk != "kubernetes") ? $each($group, function($e, $ek) {
      ($type($e) = "object" and $exists($e.version) and $exists($e.source)) ? {
        "depName": $gk & "." & $ek,
        "packageName": $e.source.package,
        "currentValue": $string($e.version),
        "datasource": $e.source.datasource,
        "registryUrl": $e.source.registry
      }
    })
  })], function($a, $v) { $append($a, $v) }, [])
)
